 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(3 * w)] for _ in range(3 * h)]
    # Each nonzero source cell expands to a tile marking the zero positions
    # of the original 3x3 pattern, in that cell's color.
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                for dr in range(3):
                    for dc in range(3):
                        if grid[dr][dc] == 0:
                            out[3 * r + dr][3 * c + dc] = value
    return out
